      groundPatch(K(0.148), 1, 26, [30, 0.20, 40], CONC_D);
      building(K(0.090), 1, 28, 12, 6.5, 30, { col: CORR_BLUE });
      building(K(0.108), 1, 28, 12, 6.0, 26, { col: CORR_CREAM });
