      building(K(0.142), 1, 56, 9, 5.0, 16, { col: FALU });
      building(K(0.112), 1, 80, 12, 6.0, 24, { col: CORR_CREAM });  // workshop
      // Motorhome / transporter row omitted — awning posts bury 5–7 cm into
