      groundPatch(K(0.185), 1, 14, [48, 0.18, 62], GRASS);
      groundPatch(K(0.205), 1, 18, [28, 0.16, 48], GRASS);   // was 40 wide: it met the widened runway apron
      groundPatch(K(0.226), 1, 22, [30, 0.20, 36], GRASS_M);
      spectatorHill(0.172, 0.212, 1, 28, {});
