        const h = hash(k * 19 + 7);
        if (h < 0.30) continue;
        if (h < 0.62) farTree(k, 1, 30 + h * 22, 6 + h * 4, SCRUB);
        else farPine(k, 1, 30 + h * 26, 11 + h * 6, PINE_D);
